window.GRAMMAR_OLD = [{"id": "g1", "lesson": 1, "title": "X は Y です", "pattern": "〜は〜です", "meaning": "X is Y", "explanation": "「は」marks the topic (what the sentence is about). 「です」is the polite copula 'is/be'.", "examples": [{"jp": "私は学生です。", "rd": "わたし は がくせい です。", "en": "I am a student."}, {"jp": "田中さんは先生です。", "rd": "たなかさん は せんせい です。", "en": "Mr. Tanaka is a teacher."}], "exercises": [{"q": "私___学生です。", "opts": ["は", "を", "に", "で"], "ans": 0}, {"q": "田中さんは医者___。", "opts": ["です", "ます", "だ", "の"], "ans": 0}]}, {"id": "g2", "lesson": 2, "title": "も (also)", "pattern": "〜も", "meaning": "also; too", "explanation": "Replaces 「は」 to mean 'also / too' for the topic.", "examples": [{"jp": "私は学生です。田中さんも学生です。", "rd": "わたし は がくせい です。 たなかさん も がくせい です。", "en": "I am a student. Mr. Tanaka is also a student."}], "exercises": [{"q": "私も日本人___。", "opts": ["は", "です", "ます", "を"], "ans": 1}]}, {"id": "g3", "lesson": 3, "title": "の (possession)", "pattern": "AのB", "meaning": "A's B; B of A", "explanation": "「の」connects two nouns; the first modifies the second.", "examples": [{"jp": "これは私の本です。", "rd": "これは わたし の ほん です。", "en": "This is my book."}, {"jp": "日本語の学校です。", "rd": "にほんご の がっこう です。", "en": "It is a Japanese-language school."}], "exercises": [{"q": "これは私___本です。", "opts": ["の", "は", "も", "が"], "ans": 0}]}, {"id": "g4", "lesson": 4, "title": "か (question)", "pattern": "〜ですか", "meaning": "...? (question)", "explanation": "Add 「か」 at the end of a sentence to make a question. No word order change needed.", "examples": [{"jp": "あなたは学生ですか。", "rd": "あなた は がくせい です か。", "en": "Are you a student?"}, {"jp": "トイレはどこですか。", "rd": "トイレ は どこ です か。", "en": "Where is the toilet?"}], "exercises": [{"q": "あなたは先生です___。", "opts": ["か", "の", "は", "も"], "ans": 0}]}, {"id": "g5", "lesson": 5, "title": "これ・それ・あれ", "pattern": "これ／それ／あれ", "meaning": "this / that / that over there", "explanation": "これ = near speaker; それ = near listener; あれ = away from both.", "examples": [{"jp": "これはいくらですか。", "rd": "これ は いくら です か。", "en": "How much is this?"}, {"jp": "それは私の傘です。", "rd": "それ は わたし の かさ です。", "en": "That is my umbrella."}], "exercises": [{"q": "（指着自己手里的东西）___は何ですか。", "opts": ["それ", "あれ", "これ", "どれ"], "ans": 2}]}, {"id": "g6", "lesson": 6, "title": "ここ・そこ・あそこ", "pattern": "ここ／そこ／あそこ", "meaning": "here / there / over there", "explanation": "Place words: ここ = here (near speaker), そこ = there, あそこ = over there.", "examples": [{"jp": "駅はあそこです。", "rd": "えき は あそこ です。", "en": "The station is over there."}], "exercises": [{"q": "トイレは___ですか。— あそこです。", "opts": ["ここ", "そこ", "どこ", "だれ"], "ans": 2}]}, {"id": "g7", "lesson": 7, "title": "へ (direction)", "pattern": "〜へ行きます", "meaning": "go to ...", "explanation": "「へ」(read 'e') marks the destination of movement verbs like 行きます, 来ます, 帰ります.", "examples": [{"jp": "学校へ行きます。", "rd": "がっこう へ いきます。", "en": "I go to school."}, {"jp": "日本へ来ました。", "rd": "にほん へ きました。", "en": "I came to Japan."}], "exercises": [{"q": "明日、東京___行きます。", "opts": ["へ", "を", "の", "は"], "ans": 0}]}, {"id": "g8", "lesson": 8, "title": "を (object)", "pattern": "〜を〜ます", "meaning": "do ... (object)", "explanation": "「を」 marks the direct object of an action.", "examples": [{"jp": "パンを食べます。", "rd": "パン を たべます。", "en": "I eat bread."}, {"jp": "音楽を聞きます。", "rd": "おんがく を ききます。", "en": "I listen to music."}], "exercises": [{"q": "水___飲みます。", "opts": ["を", "へ", "に", "と"], "ans": 0}]}, {"id": "g9", "lesson": 9, "title": "で (place / means)", "pattern": "〜で", "meaning": "at (place); by means of", "explanation": "「で」 marks where an action happens, or the tool/means used.", "examples": [{"jp": "図書館で勉強します。", "rd": "としょかん で べんきょう します。", "en": "I study at the library."}, {"jp": "バスで行きます。", "rd": "バス で いきます。", "en": "I go by bus."}], "exercises": [{"q": "レストラン___昼ご飯を食べます。", "opts": ["で", "に", "を", "へ"], "ans": 0}, {"q": "電車___東京へ行きます。", "opts": ["で", "を", "が", "と"], "ans": 0}]}, {"id": "g10", "lesson": 10, "title": "に (time / destination)", "pattern": "〜に", "meaning": "at (time); to (person/place)", "explanation": "「に」 marks a specific point in time, the destination with certain verbs, or the receiver of an action.", "examples": [{"jp": "七時に起きます。", "rd": "しちじ に おきます。", "en": "I get up at 7 o'clock."}, {"jp": "友達に電話します。", "rd": "ともだち に でんわ します。", "en": "I call my friend."}], "exercises": [{"q": "九時___寝ます。", "opts": ["に", "で", "を", "は"], "ans": 0}]}, {"id": "g11", "lesson": 11, "title": "から・まで", "pattern": "〜から〜まで", "meaning": "from ... to/until ...", "explanation": "「から」 = from; 「まで」 = until/to. Used for times and places.", "examples": [{"jp": "九時から五時まで働きます。", "rd": "くじ から ごじ まで はたらきます。", "en": "I work from 9 to 5."}, {"jp": "東京から大阪まで行きます。", "rd": "とうきょう から おおさか まで いきます。", "en": "I go from Tokyo to Osaka."}], "exercises": [{"q": "月曜日___金曜日まで働きます。", "opts": ["から", "に", "で", "を"], "ans": 0}]}, {"id": "g12", "lesson": 12, "title": "と・や", "pattern": "AとB／AやB", "meaning": "A and B / A and B (etc.)", "explanation": "「と」 lists exhaustively; 「や」 gives examples (not a complete list).", "examples": [{"jp": "本とノートを買います。", "rd": "ほん と ノート を かいます。", "en": "I buy a book and a notebook."}, {"jp": "果物や野菜を買います。", "rd": "くだもの や やさい を かいます。", "en": "I buy fruit, vegetables, and so on."}], "exercises": [{"q": "パン___卵を買いました。", "opts": ["と", "や", "は", "へ"], "ans": 0}]}, {"id": "g13", "lesson": 13, "title": "ます形", "pattern": "〜ます／〜ません", "meaning": "polite present / negative", "explanation": "〜ます = do (present/future), 〜ません = don't do.", "examples": [{"jp": "毎日勉強します。", "rd": "まいにち べんきょう します。", "en": "I study every day."}, {"jp": "お酒は飲みません。", "rd": "おさけ は のみません。", "en": "I don't drink alcohol."}], "exercises": [{"q": "明日、学校へ行___。", "opts": ["きます", "きません", "きる", "かった"], "ans": 0}]}, {"id": "g14", "lesson": 14, "title": "ました・ませんでした", "pattern": "〜ました／〜ませんでした", "meaning": "polite past / past negative", "explanation": "〜ました = did; 〜ませんでした = did not do.", "examples": [{"jp": "昨日、映画を見ました。", "rd": "きのう えいが を みました。", "en": "I watched a movie yesterday."}, {"jp": "昨日、勉強しませんでした。", "rd": "きのう べんきょう しませんでした。", "en": "I didn't study yesterday."}], "exercises": [{"q": "朝ご飯を食べ___。", "opts": ["ました", "ません", "ます", "ましょう"], "ans": 0}]}, {"id": "g15", "lesson": 15, "title": "て形", "pattern": "〜て、〜て、〜ます", "meaning": "and then; connecting actions", "explanation": "The て-form connects multiple actions in sequence.", "examples": [{"jp": "朝起きて、顔を洗います。", "rd": "あさ おきて かお を あらいます。", "en": "I get up in the morning and wash my face."}], "exercises": [{"q": "駅へ行って、電車___乗ります。", "opts": ["に", "を", "で", "へ"], "ans": 0}]}, {"id": "g16", "lesson": 16, "title": "てください", "pattern": "〜てください", "meaning": "please do ...", "explanation": "Request someone to do something politely.", "examples": [{"jp": "ちょっと待ってください。", "rd": "ちょっと まって ください。", "en": "Please wait a moment."}, {"jp": "ここに名前を書いてください。", "rd": "ここ に なまえ を かいて ください。", "en": "Please write your name here."}], "exercises": [{"q": "写真を撮___ください。", "opts": ["って", "ます", "たい", "ないで"], "ans": 0}]}, {"id": "g17", "lesson": 17, "title": "てもいいです", "pattern": "〜てもいいですか", "meaning": "may I ...?", "explanation": "Asking permission to do something.", "examples": [{"jp": "写真を撮ってもいいですか。", "rd": "しゃしん を とっても いい です か。", "en": "May I take a photo?"}], "exercises": [{"q": "ここに座___もいいですか。", "opts": ["って", "たい", "ます", "なく"], "ans": 0}]}, {"id": "g18", "lesson": 18, "title": "てはいけません", "pattern": "〜てはいけません", "meaning": "must not ...", "explanation": "Expresses prohibition.", "examples": [{"jp": "ここでたばこを吸ってはいけません。", "rd": "ここ で たばこ を すっては いけません。", "en": "You must not smoke here."}], "exercises": [{"q": "図書館で話して___。", "opts": ["はいけません", "もいいです", "ください", "います"], "ans": 0}]}, {"id": "g19", "lesson": 19, "title": "ています", "pattern": "〜ています", "meaning": "be doing ... (progressive)", "explanation": "Action in progress now, or a continuing state.", "examples": [{"jp": "今、ご飯を食べています。", "rd": "いま ごはん を たべて います。", "en": "I am eating now."}, {"jp": "田中さんは結婚しています。", "rd": "たなかさん は けっこんして います。", "en": "Mr. Tanaka is married."}], "exercises": [{"q": "兄は東京に住んで___。", "opts": ["います", "あります", "します", "いきます"], "ans": 0}]}, {"id": "g20", "lesson": 20, "title": "たいです", "pattern": "〜たいです", "meaning": "want to do ...", "explanation": "Attach たい to the verb stem; describes the speaker's desire.", "examples": [{"jp": "日本へ行きたいです。", "rd": "にほん へ いきたい です。", "en": "I want to go to Japan."}, {"jp": "寿司が食べたいです。", "rd": "すしが たべたい です。", "en": "I want to eat sushi."}], "exercises": [{"q": "水が飲___です。", "opts": ["みたい", "ます", "て", "ません"], "ans": 0}]}, {"id": "g21", "lesson": 21, "title": "ましょう・ませんか", "pattern": "〜ましょう／〜ませんか", "meaning": "let's ... / shall we ...?", "explanation": "〜ませんか = inviting 'shall we?'; 〜ましょう = 'let's do'.", "examples": [{"jp": "一緒に昼ご飯を食べませんか。", "rd": "いっしょ に ひるごはん を たべません か。", "en": "Shall we have lunch together?"}, {"jp": "映画を見ましょう。", "rd": "えいが を みましょう。", "en": "Let's watch a movie."}], "exercises": [{"q": "一緒に行き___か。", "opts": ["ましょう", "ません", "たい", "ました"], "ans": 0}]}, {"id": "g22", "lesson": 22, "title": "あります・います", "pattern": "〜が あります／います", "meaning": "there is ... (thing / living)", "explanation": "あります for inanimate things; います for people/animals.", "examples": [{"jp": "机の上に本があります。", "rd": "つくえ の うえ ほん が あります。", "en": "There is a book on the desk."}, {"jp": "公園に子供がいます。", "rd": "こうえん に こども が います。", "en": "There are children in the park."}], "exercises": [{"q": "教室に学生___。", "opts": ["がいます", "があります", "をいます", "にいます"], "ans": 0}]}, {"id": "g23", "lesson": 23, "title": "好きです・上手です", "pattern": "〜が好きです／上手です", "meaning": "like ... / be good at ...", "explanation": "Emotion and ability adjectives take 「が」.", "examples": [{"jp": "私は日本語が好きです。", "rd": "わたし は にほんご が すき です。", "en": "I like Japanese."}, {"jp": "彼は料理が上手です。", "rd": "かれ は りょうり が じょうず です。", "en": "He is good at cooking."}], "exercises": [{"q": "私は犬___好きです。", "opts": ["が", "を", "は", "へ"], "ans": 0}]}, {"id": "g24", "lesson": 24, "title": "い形容詞", "pattern": "高い／高くない", "meaning": "i-adjectives", "explanation": "い-adjectives end in い: negative → くない, past → かった.", "examples": [{"jp": "この本は高いです。", "rd": "この ほん は たかい です。", "en": "This book is expensive."}, {"jp": "昨日は寒くなかったです。", "rd": "きのう は さむくなかった です。", "en": "It wasn't cold yesterday."}], "exercises": [{"q": "この傘は高___です。", "opts": ["い", "な", "の", "く"], "ans": 0}]}, {"id": "g25", "lesson": 25, "title": "な形容詞", "pattern": "静かな／静かじゃない", "meaning": "na-adjectives", "explanation": "な-adjectives take な before nouns; negative → じゃないです.", "examples": [{"jp": "この町は静かです。", "rd": "この まち は しずか です。", "en": "This town is quiet."}, {"jp": "きれいな花ですね。", "rd": "きれいな はな ですね。", "en": "What a beautiful flower."}], "exercises": [{"q": "彼女は元気___人です。", "opts": ["な", "い", "の", "で"], "ans": 0}]}, {"id": "g26", "lesson": 26, "title": "より・のほうが", "pattern": "AよりBのほうが〜", "meaning": "B is more ... than A", "explanation": "Comparison: より marks the standard of comparison.", "examples": [{"jp": "電車よりバスのほうが安いです。", "rd": "でんしゃ より バス のほうが やすい です。", "en": "The bus is cheaper than the train."}], "exercises": [{"q": "犬___猫のほうが好きです。", "opts": ["より", "から", "まで", "が"], "ans": 0}]}, {"id": "g27", "lesson": 27, "title": "一番", "pattern": "〜が一番〜", "meaning": "the most ... / the best ...", "explanation": "Superlative: 一番 = number one.", "examples": [{"jp": "一年で一番寒い月は一月です。", "rd": "いちねん で いちばん さむい つき は いちがつ です。", "en": "The coldest month of the year is January."}], "exercises": [{"q": "果物の中___りんごが一番好きです。", "opts": ["で", "に", "を", "は"], "ans": 0}]}, {"id": "g28", "lesson": 28, "title": "ことができます", "pattern": "〜ことができます", "meaning": "can do ...", "explanation": "Verb (dictionary form) + ことができます = be able to.", "examples": [{"jp": "日本語を話すことができます。", "rd": "にほんご を はなす ことが できます。", "en": "I can speak Japanese."}], "exercises": [{"q": "ピアノを弾くことが___。", "opts": ["できます", "します", "あります", "いきます"], "ans": 0}]}, {"id": "g29", "lesson": 29, "title": "たり〜たり", "pattern": "〜たり〜たりします", "meaning": "do things like ... and ...", "explanation": "Lists example actions.", "examples": [{"jp": "日曜日は本を読んだり音楽を聞いたりします。", "rd": "にちようび ほん を よんだり おんがく を きいたり します。", "en": "On Sundays I read books, listen to music, and so on."}], "exercises": [{"q": "休みの日は買い物___散歩したりします。", "opts": ["したり", "して", "しますます", "ました"], "ans": 0}]}, {"id": "g30", "lesson": 30, "title": "〜と思います", "pattern": "〜と思います", "meaning": "I think that ...", "explanation": "Opinion: plain form + と思います.", "examples": [{"jp": "明日は雨が降ると思います。", "rd": "あした は あめが ふると おもいます。", "en": "I think it will rain tomorrow."}], "exercises": [{"q": "日本語は難しいと___。", "opts": ["思います", "あります", "します", "考えますます"], "ans": 0}]}, {"id": "g31", "lesson": 31, "title": "〜つもりです", "pattern": "〜つもりです", "meaning": "intend to ...", "explanation": "Plain form + つもりです = plan/intention.", "examples": [{"jp": "来年、日本へ行くつもりです。", "rd": "らいねん にほん へ いく つもり です。", "en": "I intend to go to Japan next year."}], "exercises": [{"q": "大学で日本語を勉強する___です。", "opts": ["つもり", "こと", "もの", "ため"], "ans": 0}]}, {"id": "g32", "lesson": 32, "title": "〜ましょうか", "pattern": "〜ましょうか", "meaning": "shall I ...? (offering)", "explanation": "Offering to do something for someone.", "examples": [{"jp": "傘を貸しましょうか。", "rd": "かさ を かしましょう か。", "en": "Shall I lend you an umbrella?"}], "exercises": [{"q": "荷物を持ち___か。", "opts": ["ましょう", "ません", "たい", "ました"], "ans": 0}]}];
